    CMainGameComponent::Get()->PeekPlayerManager().GetMainPlayer().PeekPControlledCreature()->PeekTC(TCI_HERO_STATS, &pHeroStats);
    pGoldText->SetValue(GFIntToWideString(pHeroStats->GetMoney()), true, true);

